WITH with_windows AS (SELECT id, email, manager_id, job_title, salary, SUM(salary) OVER (PARTITION BY job_title ORDER BY hire_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_salary, MAX(salary) OVER (PARTITION BY job_title ORDER BY hire_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_salary, MIN(salary) OVER (PARTITION BY job_title ORDER BY hire_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_salary, COUNT(salary) OVER (PARTITION BY job_title ORDER BY hire_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_salary, LAG(salary, 1) OVER (PARTITION BY level ORDER BY salary, id) AS prev_salary FROM employees) SELECT CASE WHEN running_min_salary >= 144000 THEN 'LARGE' ELSE 'SMALL' END AS running_min_salary_tier, manager_id, COUNT(*) AS row_count, STDDEV_SAMP(salary) AS salary_stddev, AVG(running_count_salary) AS avg_running_count_salary, COUNT(DISTINCT id) AS distinct_ids, GROUPING_ID() AS grouping_level FROM with_windows GROUP BY GROUPING SETS ((CASE WHEN running_min_salary >= 144000 THEN 'LARGE' ELSE 'SMALL' END, manager_id), (CASE WHEN running_min_salary >= 144000 THEN 'LARGE' ELSE 'SMALL' END), ())
